{
  "findings": [
    {
      "ref": "[D516]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child.",
      "stance": "risk",
      "quote": "Kids can set their own passcode to keep siblings out of their profile, but parents can override it or create it themselves."
    },
    {
      "ref": "[D516]",
      "area": "money",
      "claim": "The app pushes in-app purchases and branded content that may be hard for kids to recognize as ads.",
      "stance": "risk",
      "quote": "Some videos contain kid-focused ads (e.g., for TV shows and websites like Mother Goose Club and Discover the Forest. Some look more like contests and entertainment than ads, making it hard for kids to know they're being marketed to. Videos featuring branded content aren't marked as advertising, are mixed in with other videos. Parents have reported seeing occasional ads with inappropriate content. Some videos are focused on products (e.g., backpacks, toy sets), often titled and filed under \"Unbox It\" (e.g., a video on the Brick Queen channel features unboxing of a Pokémon toy). Other branded content includes videos featuring Disney dolls, Hasbro products, and whole channels from brands such as McDonald's (with videos about Happy Meal toys)."
    },
    {
      "ref": "[D516]",
      "area": "data",
      "claim": "The app collects user information and shares it with third parties, and the privacy policy allows changes without notice.",
      "stance": "risk",
      "quote": "Read the developer's privacy notice for details on how your (or your kids') information is collected, used, and shared and any choices you may have in the matter, and note that privacy policies and terms of service frequently change."
    },
    {
      "ref": "[D516]",
      "area": "age_gating",
      "claim": "A parent reports that the age‑gating works in practice, with categories like Preschool, Younger, and Older, but the Older category can expose kids to more mature content.",
      "stance": "mitigation",
      "quote": "Note that if you choose \"Older,\" there's a warning that kids will see more mature content; it can include words like \"f--k,\" scantily clad dancers, and mildly sexy content, though direct searches for those things don't work."
    },
    {
      "ref": "[D516]",
      "area": "content",
      "claim": "A parent reports that the app may show mild cartoon violence, creepy images, and suggestive content such as crotch‑grabbing during a Michael Jackson dance tutorial.",
      "stance": "risk",
      "quote": "There's some potentially creepy images for younger viewers, as in \"Figaro Pho,\" which features a character who faces phobias and is drawn in a Tim Burton style. Curated content is updated periodically, so degrees of violence and scariness may fluctuate. Also, sometimes scary images are embedded in what at first seem to be kid‑friendly videos. ... videos containing racy and explicit images (from crotch grabbing during a Michael Jackson dance tutorial to nudity)."
    },
    {
      "ref": "[D516]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory scrutiny and fines related to children's privacy.",
      "stance": "risk",
      "quote": "YouTube Kids reportedly doesn't allow videos with references that are paid advertising, but the app has drawn lots of public scrutiny and controversy for including some clearly inappropriate videos and ads (with nudity, alcohol, and profanity), as well as fast‑food and junk food ads that push unhealthy food."
    }
  ]
}
